package org.mockito;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.hamcrest.Matcher;
import org.hamcrest.core.IsNull;
import org.junit.*;
import org.junit.Test;
import org.mockito.internal.matchers.*;
import org.mockito.internal.matchers.apachecommons.ReflectionEquals;
import org.mockito.internal.progress.HandyReturnValues;
import org.mockito.internal.progress.MockingProgress;
import org.mockito.internal.progress.ThreadSafeMockingProgress;
import static org.junit.Assert.*;
import static org.junit.Assert.assertNotNull;
import static org.mockito.Matchers.anyMap;

public class Matchers_anyMap_TriageGen1Test {

    @Test
    public void testAnyMapReturnsNotNullMap() {
        // The method anyMap() is a Mockito matcher used during stubbing or verification.
        // It returns a Matcher that, when evaluated, returns a Map.
        // Since it's a static utility for argument matching, we test that it returns a non-null object
        // that can be assigned to a Map type.
        Map result = anyMap();
        assertNotNull("anyMap() should return a non-null object representing a Map matcher", result);
    }

    @Test
    public void testAnyMapType() {
        // Verify the return type is indeed Map
        Object result = anyMap();
        assert(result instanceof Map);
    }
}
